root=EvaluateActionModel(evaluate=evaluate_Params(code="(function(){
try {
  // Change reservation type from Dine in to Events
  const selectElement = document.getElementById('reservations-city-search-type');
  if (selectElement && selectElement.shadowRoot) {
    const optionsList = selectElement.shadowRoot.querySelector('[role=listbox]');
    if (optionsList) {
      // Find Events option by text content
      const options = Array.from(optionsList.children);
      const eventsOption = options.find(opt => opt.textContent.includes('Events'));
      if (eventsOption) {
        eventsOption.click();
        return { success: true, message: 'Reservation type changed to Events', selectedText: eventsOption.textContent };
      }
      return { success: false, message: 'Events option not found', optionsCount: options.length };
    }
    return { success: false, message: 'Options list not found in shadow DOM' };
  }
  return { success: false, message: 'Reservation type select not found or no shadowRoot', elementFound: !!selectElement };
} catch(e) {
  return { success: false, message: e.message };
}
})()"))
